package main

import (
	"database/sql"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// handleReport generates a PDF report by invoking wkhtmltopdf with user-supplied HTML
func handleReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	templateID := r.URL.Query().Get("template")
	if templateID == "" {
		templateID = "default"
	}

	// Read user-provided content for the report body
	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "bad request", 400)
		return
	}
	defer r.Body.Close()

	userContent := string(body)

	// Fetch template header from database
	var header string
	query := fmt.Sprintf("SELECT header_html FROM report_templates WHERE id = '%s'", templateID)
	err = db.QueryRow(query).Scan(&header)
	if err != nil {
		header = "<h1>Report</h1>"
	}

	// Combine header with user content
	fullHTML := fmt.Sprintf("<html><body>%s<div>%s</div></body></html>", header, userContent)

	// Write to temp file
	tmpFile, err := ioutil.TempFile("", "report-*.html")
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	defer os.Remove(tmpFile.Name())
	tmpFile.WriteString(fullHTML)
	tmpFile.Close()

	outFile := strings.Replace(tmpFile.Name(), ".html", ".pdf", 1)
	defer os.Remove(outFile)

	// Generate PDF - wkhtmltopdf will fetch any resources referenced in the HTML
	cmd := exec.Command("wkhtmltopdf", "--enable-local-file-access", tmpFile.Name(), outFile)
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		http.Error(w, "pdf generation failed", 500)
		return
	}

	pdfData, err := ioutil.ReadFile(outFile)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}

	w.Header().Set("Content-Type", "application/pdf")
	w.Header().Set("Content-Disposition", "attachment; filename=report.pdf")
	w.Write(pdfData)
}

// handleHealth is a simple health check
func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/report", handleReport)
	http.HandleFunc("/health", handleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
